import{_ as s}from"./DnO5p5gA.js";import{y as o,c as l,b as r,v as i,o as n}from"./B-cM2uPT.js";const d={class:"mx-auto max-w-5xl px-6 py-12"},p={__name:"index",setup(c){o({title:"Robo.cash Review (2026) | P2P Insights",description:"A practical 2026 Robo.cash review: automated portfolios, 8–11% listed rates, deposits and withdrawals, liquidity, reliability, and the risks to understand."});const t=[{label:"Home",to:"/"},{label:"Platforms",to:"/platforms"},{label:"Robo.cash",to:"/platforms/robocash"}];return(h,e)=>{const a=s;return n(),l("main",d,[r(a,{items:t}),e[0]||(e[0]=i('<article class="space-y-10" aria-labelledby="robocash-review-title"><header class="space-y-3"><h1 id="robocash-review-title" class="text-3xl font-semibold tracking-tight text-slate-900 dark:text-white sm:text-4xl"> Robo.cash Review (2026) </h1><p class="text-lg text-slate-700 dark:text-slate-300"> Fully automated P2P investing: simple to run, slower to move cash </p></header><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> What Is Robo.cash? </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Robo.cash is a P2P investment platform focused on loan receivables. Robo.cash says it is part of UnaFinancial and that the loan originators on the platform belong to the same group. You set the portfolio rules, then the platform automatically invests the available cash for you. </p><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> The result is a genuinely low-maintenance experience. It is a good fit for an investor who wants P2P exposure without reviewing individual loans every week. The trade-off is that you get less control than on a platform with manual investing. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> How Robo.cash Works </h2><ol class="list-decimal space-y-2 pl-6 text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"><li>Register, verify your identity, and fund the account with a EUR bank transfer.</li><li>Create either a One-click portfolio or a custom portfolio.</li><li>Choose the parameters you want for a custom portfolio, such as loan originators, terms, and rates.</li><li>Let the portfolio allocate cash and reinvest according to your selected income settings.</li></ol><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> There is no manual investing. You cannot browse the primary market and select individual loans one by one; all new investments are made through automated portfolios. One-click is the fastest route, while a custom portfolio gives you some guardrails without turning the experience into active management. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Hands-On Experience: Easy and Properly Hands-Off </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> The strongest part of Robo.cash is its simplicity. After the initial portfolio setup, there is very little to do: deposited cash is allocated automatically and the account is easy to leave running. For a passive investor, that is a real advantage rather than just a marketing claim. </p><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> The limitation is equally clear. Investors who enjoy checking loan books, choosing a specific lender, or making tactical purchases will find the platform restrictive. Robo.cash lets you define a strategy, but it does not let you execute individual investment decisions. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Deposits and Withdrawals: Plan for 2–3 Business Days </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Cash movement is the main practical downside. In use, deposits and withdrawals take roughly 2–3 days rather than feeling instant. Robo.cash says incoming bank transfers can take up to three business days, and its terms allow up to two business days to process available wallet funds; its help centre says the money can arrive at your bank within three working days. </p><ul class="list-disc space-y-2 pl-6 text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"><li>Deposits are made by personal EUR bank transfer, not by card.</li><li>Available, uninvested cash can be moved to the Wallet immediately.</li><li>Wallet withdrawals have a usual minimum of EUR 50.</li><li>Invested loans need to be sold on the Secondary Market before they can become withdrawable cash.</li><li>Robo.cash says a secondary-market sale usually takes around 1–7 days, so it is not guaranteed instant liquidity.</li></ul><p class="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-800 dark:border-amber-500/40 dark:bg-amber-500/10 dark:text-amber-200"> Important: the 2–3 day estimate applies once the money is available to withdraw from your Wallet. Selling out of invested loans can add time, because another investor needs to buy those claims. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Returns and Fees </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Robo.cash currently lists annual rates from 8% to 11%, with its loyalty programme advertising rates up to 11.8% for qualifying investors. The rate depends on the loans and portfolio settings, so it is a target rate rather than a guaranteed account return. </p><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> The platform does not charge investors for deposits, withdrawals, portfolio management, or the Secondary Market. Your own bank may still charge for a transfer, and the lack of platform fees does not remove investment risk. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Reliability: Strong Track Record, but Not the Same as Protection </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Reliability has been a clear strength so far. Robo.cash says that, since its 2017 launch, investors have received repayments within the agreed timeframe or the 30-day buyback period. That history matters, especially compared with newer P2P platforms. </p><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> There are two support layers behind that record. Loan originators provide a buyback guarantee after a claim is more than 30 days overdue, and UnaFinancial says it stands behind the obligations of its affiliated lenders. Both are company commitments, not a state guarantee. </p><p class="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-800 dark:border-amber-500/40 dark:bg-amber-500/10 dark:text-amber-200"> Important: Robo.cash says it is not regulated under a financial-services licence, and investments are not covered by a deposit guarantee, investment insurance, or compensation scheme. The same-group structure improves oversight but also concentrates the risk in UnaFinancial and its lenders. </p></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Who Robo.cash Is Best For </h2><ul class="list-disc space-y-2 pl-6 text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"><li>Investors who want a straightforward, hands-off P2P allocation.</li><li>People happy to choose broad portfolio rules instead of individual loans.</li><li>Investors who can leave money invested and do not need immediate access to it.</li><li>Those who value the platform’s repayment history but still diversify across providers and asset types.</li></ul></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Who Should Look Elsewhere </h2><ul class="list-disc space-y-2 pl-6 text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"><li>Anyone who needs instant deposits, withdrawals, or emergency-fund liquidity.</li><li>Investors who want to select each loan or lending company manually.</li><li>Those looking for a regulated investment service or formal investor compensation cover.</li><li>Anyone uncomfortable with the credit and group-risk concentration behind the platform.</li></ul></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Pros &amp; Cons Summary </h2><div class="grid gap-4 sm:grid-cols-2"><div class="rounded-xl border border-emerald-300 bg-emerald-50 p-4 dark:border-emerald-500/40 dark:bg-emerald-500/10"><h3 class="text-lg font-semibold text-emerald-800 dark:text-emerald-200"> Pros </h3><ul class="mt-2 list-disc space-y-1 pl-6 text-sm text-emerald-900 dark:text-emerald-100"><li>Easy, genuinely hands-off portfolio management.</li><li>No manual loan selection required.</li><li>Listed annual rates of 8–11%.</li><li>No Robo.cash investor fees for core platform actions.</li><li>Strong historical repayment record since 2017.</li><li>30-day buyback and stated UnaFinancial support structure.</li><li>Secondary Market available for early exits.</li></ul></div><div class="rounded-xl border border-rose-300 bg-rose-50 p-4 dark:border-rose-500/40 dark:bg-rose-500/10"><h3 class="text-lg font-semibold text-rose-800 dark:text-rose-200"> Cons </h3><ul class="mt-2 list-disc space-y-1 pl-6 text-sm text-rose-900 dark:text-rose-100"><li>Deposits and Wallet withdrawals normally take 2–3 business days.</li><li>No manual investing or individual primary-market loan selection.</li><li>All originators belong to the same group, creating concentration risk.</li></ul></div></div></section><section class="space-y-3"><h2 class="text-2xl font-semibold text-slate-900 dark:text-white"> Final Verdict </h2><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Robo.cash is one of the more convenient P2P choices for an investor who wants to set a strategy and stay out of the way. The automated model is its real advantage: it is simple, tidy, and does not demand constant attention. </p><p class="text-base leading-relaxed text-slate-700 dark:text-slate-300 sm:text-lg"> Go in with the right expectations. Transfers are measured in business days, not minutes; the lack of manual control is deliberate; and a good payment record does not make the investment risk-free. As a diversified, long-term P2P allocation rather than cash savings, Robo.cash makes the most sense. </p></section><section class="rounded-2xl border border-slate-200 bg-slate-50 p-6 dark:border-slate-800 dark:bg-slate-900/50" aria-label="Robo.cash research sources"><h2 class="text-xl font-semibold text-slate-900 dark:text-white"> Research sources </h2><p class="mt-2 text-sm leading-relaxed text-slate-700 dark:text-slate-300"> Platform details were checked against Robo.cash’s official <a href="https://robo.cash/how-it-works" target="_blank" rel="noopener noreferrer" class="font-medium underline underline-offset-2 hover:text-slate-950 dark:hover:text-white">how-it-works overview</a>, <a href="https://robo.cash/questions/12/38" target="_blank" rel="noopener noreferrer" class="font-medium underline underline-offset-2 hover:text-slate-950 dark:hover:text-white">automated-investing FAQ</a>, <a href="https://robo.cash/questions/10/30" target="_blank" rel="noopener noreferrer" class="font-medium underline underline-offset-2 hover:text-slate-950 dark:hover:text-white">withdrawal guidance</a>, and <a href="https://robo.cash/questions/5/20" target="_blank" rel="noopener noreferrer" class="font-medium underline underline-offset-2 hover:text-slate-950 dark:hover:text-white">risk disclosure</a>. </p></section></article>',1))])}}};export{p as default};
